using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Windows;
namespace FoolLauncher {public static class LocalModImportTests {
 static void Assert(bool value,string message){if(!value)throw new Exception(message);}
 static void Reject(Action action){bool denied=false;try{action();}catch(IOException){denied=true;}catch(InvalidDataException){denied=true;}catch(OperationCanceledException){denied=true;}Assert(denied,"Invalid or blocked mod import accepted");}
 static string Jar(string folder,string name,string id){string path=Path.Combine(folder,name);using(var zip=ZipFile.Open(path,ZipArchiveMode.Create))using(var w=new StreamWriter(zip.CreateEntry(id==null?"test.txt":"fabric.mod.json").Open()))w.Write(id==null?"ordinary jar":"{\"id\":\""+id+"\",\"name\":\"Test\",\"version\":\"1\"}");return path;}
 static void Routed(IDataObject payload){var child=new System.Windows.Controls.Button();var zone=new System.Windows.Controls.Border{Child=child};var hint=new System.Windows.Controls.TextBlock();bool busy=false,game=false;int imported=0,errors=0;new ModDrop(zone,hint,()=>busy,()=>game,files=>{imported++;return System.Threading.Tasks.Task.FromResult(0);},message=>errors++);Func<RoutedEvent,DragEventArgs> make=kind=>{var ctor=typeof(DragEventArgs).GetConstructor(System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance,null,new[]{typeof(IDataObject),typeof(DragDropKeyStates),typeof(DragDropEffects),typeof(DependencyObject),typeof(Point)},null);var e=(DragEventArgs)ctor.Invoke(new object[]{payload,DragDropKeyStates.LeftMouseButton,DragDropEffects.Copy|DragDropEffects.Move,child,new Point(1,1)});e.RoutedEvent=kind;return e;};var hover=make(DragDrop.PreviewDragEnterEvent);child.RaiseEvent(hover);Assert(hover.Handled&&hover.Effects==DragDropEffects.Copy&&zone.BorderThickness.Left==2,"Nested mod-drop hover did not accept copy");var drop=make(DragDrop.PreviewDropEvent);child.RaiseEvent(drop);Assert(drop.Handled&&imported==1&&zone.BorderThickness.Left==0,"Nested mod-drop did not dispatch");busy=true;child.RaiseEvent(make(DragDrop.PreviewDropEvent));busy=false;game=true;child.RaiseEvent(make(DragDrop.PreviewDropEvent));Assert(imported==1&&errors==2,"Mod drop ignored busy/game guards");}
 public static void Run(string parent){string root=Path.Combine(parent,"local-import"),source=Path.Combine(root,"sources");Directory.CreateDirectory(source);string jar=Jar(source,"test.jar","test"),ordinary=Jar(source,"ordinary.jar",null),bad=Path.Combine(source,"bad.jar"),zip=Path.Combine(source,"not-mod.zip");File.WriteAllText(bad,"not zip");File.WriteAllText(zip,"zip");var service=new PackService(Path.Combine(root,"launcher"));var instance=new Instance{Id="target",Name="Target",Minecraft="1.20.1",Loader="fabric-loader 0.16.14"};Directory.CreateDirectory(service.Folder(instance));Json.Write(Path.Combine(service.Folder(instance),"launcher-instance.json"),instance);Json.Write(Path.Combine(service.Folder(instance),"pack-index.json"),new PackIndex{game="minecraft",formatVersion=1,name="Target",versionId="1",dependencies=new Dictionary<string,string>{{"minecraft","1.20.1"},{"fabric-loader","0.16.14"}},files=new PackFile[0]});string mods=Path.Combine(service.Game(instance),"mods");var payload=new DataObject();payload.SetData(DataFormats.FileDrop,new[]{jar,jar});Routed(payload);Assert(LocalModImport.Files(payload).Length==1,"File drop deduplication failed");Reject(()=>LocalModImport.Paths(new[]{zip}));Reject(()=>LocalModImport.Paths(new[]{source}));Reject(()=>LocalModImport.Validate(ordinary));Reject(()=>LocalModImport.Validate(bad));Reject(()=>LocalModImport.Install(service,instance,new[]{jar,ordinary},()=>false,CancellationToken.None).GetAwaiter().GetResult());Assert(!Directory.GetFiles(mods).Any(),"Mixed invalid batch partially installed");string original=LauncherUpdateCore.HashFile(jar);int count=LocalModImport.Install(service,instance,new[]{jar},()=>false,CancellationToken.None).GetAwaiter().GetResult();Assert(count==1&&File.Exists(Path.Combine(mods,"test.jar"))&&LauncherUpdateCore.HashFile(jar)==original,"Import failed or moved source");Assert(LocalModImport.Install(service,instance,new[]{jar},()=>false,CancellationToken.None).GetAwaiter().GetResult()==0,"Duplicate import added another mod");string duplicate=Jar(source,"test-v2.jar","test");using(var a=ZipFile.Open(duplicate,ZipArchiveMode.Update))using(var w=new StreamWriter(a.CreateEntry("different.txt").Open()))w.Write("new version");Reject(()=>LocalModImport.Install(service,instance,new[]{duplicate},()=>false,CancellationToken.None).GetAwaiter().GetResult());string another=Jar(source,"another.jar","another");Reject(()=>LocalModImport.Install(service,instance,new[]{another},()=>true,CancellationToken.None).GetAwaiter().GetResult());using(var c=new CancellationTokenSource()){c.Cancel();Reject(()=>LocalModImport.Install(service,instance,new[]{another},()=>false,c.Token).GetAwaiter().GetResult());}Assert(Directory.GetFiles(mods).Length==1,"Failed import changed target");Console.WriteLine("PASS: local mod drop format/content validation, mixed-batch atomicity, source preservation, duplicate hash/ID guards, blocked-game and cancellation checks.");}
}}
